// This file is not generated by Speakeasy — it adds --wait to
// 'vf test run create-suite', so one command starts a suite, waits until every
// run in it has finished, prints the results and exits non-zero unless every
// run passed. CI can gate on the exit code, and a person or an agent does not
// have to repeat 'vf test run wait-suite' by hand.
//
// The API caps one wait at 120 seconds, because a request held open for the
// half hour a suite can take would be cut off by proxies and by agents' command
// timeouts. So the loop lives here: it waits in 45-second calls until the suite
// is done or --max-wait runs out.
//
// It also lets --test-ids and --folder-ids take comma-separated IDs. They are
// generated as repeatable string arrays, which do not split on commas, so
// '--test-ids a,b' used to send the single ID "a,b" and fail with a 404.
//
// Hooked in by one line in createsuite.go, which a regeneration could drop
// without anything failing to compile; test/run-suite-wait.test.ts covers it.

package run

import (
	"context"
	"errors"
	"fmt"
	"math"
	"net/url"
	"strings"
	"time"

	"github.com/spf13/cobra"
	"github.com/spf13/pflag"
	"github.com/voiceflow/cli/internal/client"
	"github.com/voiceflow/cli/internal/config"
	"github.com/voiceflow/cli/internal/flagutil"
	"github.com/voiceflow/cli/internal/interactive"
	"github.com/voiceflow/cli/internal/output"
	"github.com/voiceflow/cli/internal/sdk"
	"github.com/voiceflow/cli/internal/sdk/models/components"
	"github.com/voiceflow/cli/internal/sdk/models/operations"
	"github.com/voiceflow/cli/internal/sdk/models/sdkerrors"
	"github.com/voiceflow/cli/internal/usage"
)

const (
	suiteWaitFlag    = "wait"
	suiteMaxWaitFlag = "max-wait"

	suiteDefaultMaxWait = 30 * time.Minute

	// The API accepts 5 to 120 seconds per wait. 45 keeps each request well
	// under the timeouts of proxies and agent harnesses.
	suiteWaitCallSeconds    = 45
	suiteWaitMinCallSeconds = 5
	// Headroom on top of the server-side wait before the request is abandoned.
	suiteWaitRequestSlack = 30 * time.Second
	// How much sooner than --timeout a wait asks the API to answer.
	suiteWaitTimeoutHeadroom = 5 * time.Second
	// The least time between two waits, should the API answer early without
	// the suite being done.
	suiteWaitMinInterval = 2 * time.Second

	suiteWaitRetries    = 3
	suiteWaitRetryDelay = 5 * time.Second
)

var suiteIDFlags = []string{"test-ids", "folder-ids"}

// addCreateSuiteWait registers --wait and --max-wait on create-suite and wraps
// its RunE. Without --wait the generated command runs unchanged.
func addCreateSuiteWait(cmd *cobra.Command) {
	cmd.Flags().Bool(suiteWaitFlag, false,
		"Wait until every run in the suite has finished, then print the results. Exits non-zero unless every run passed.")
	cmd.Flags().Duration(suiteMaxWaitFlag, suiteDefaultMaxWait,
		"With --wait, how long to wait in total (e.g. 10m). The suite keeps running after that; keep waiting with 'vf test run wait-suite'.")
	for _, name := range suiteIDFlags {
		if flag := cmd.Flags().Lookup(name); flag != nil {
			flag.Usage += " Separate IDs with commas or repeat the flag."
		}
	}

	cmd.Long += `

With --wait, the command waits until every run has finished, then prints the
suite's results: counts, and the runs that did not pass with their failed checks.
It exits 0 only when every run passed. It exits 1 when a run failed or was
canceled, or when --max-wait (30 minutes by default) ran out first.`
	cmd.Example += `
  vf test run create-suite --project-id <id> --environment-alias <value> --all --wait
  vf test run create-suite --project-id <id> --environment-alias <value> --test-ids <id>,<id> --wait
  vf test run create-suite --project-id <id> --environment-alias <value> --folder-ids <id> --wait --max-wait 10m`

	runCreateSuite := cmd.RunE
	cmd.RunE = func(cmd *cobra.Command, args []string) error {
		if usage.UsageRequested(cmd) {
			return runCreateSuite(cmd, args)
		}
		wait, _ := flagutil.GetBoolFlag(cmd, suiteWaitFlag)
		if cmd.Flags().Changed(suiteMaxWaitFlag) && !wait {
			return fmt.Errorf("--%s only applies with --%s", suiteMaxWaitFlag, suiteWaitFlag)
		}
		// Prompted here rather than in the generated RunE, so IDs typed into the
		// prompt are split too. Once the flags are set, it does not prompt again.
		if interactive.ShouldPrompt(cmd, createSuiteCmdMeta) {
			if err := interactive.PromptAndSetFlags(cmd, createSuiteCmdMeta); err != nil {
				return err
			}
		}
		if err := splitSuiteIDFlags(cmd); err != nil {
			return err
		}
		if !wait || client.IsDryRun(cmd) {
			return runCreateSuite(cmd, args)
		}
		return runCreateSuiteAndWait(cmd)
	}
}

// splitSuiteIDFlags splits each value of --test-ids and --folder-ids on commas.
func splitSuiteIDFlags(cmd *cobra.Command) error {
	for _, name := range suiteIDFlags {
		flag := cmd.Flags().Lookup(name)
		if flag == nil || !flag.Changed {
			continue
		}
		values, ok := flag.Value.(pflag.SliceValue)
		if !ok {
			continue
		}
		if err := values.Replace(splitIDs(values.GetSlice())); err != nil {
			return fmt.Errorf("invalid --%s: %w", name, err)
		}
	}
	return nil
}

func splitIDs(values []string) []string {
	ids := make([]string, 0, len(values))
	for _, value := range values {
		for _, id := range strings.Split(value, ",") {
			if id = strings.TrimSpace(id); id != "" {
				ids = append(ids, id)
			}
		}
	}
	return ids
}

// runCreateSuiteAndWait starts the suite the way runCreateSuiteCmd does, then
// waits for it and reports the outcome.
func runCreateSuiteAndWait(cmd *cobra.Command) error {
	maxWait, err := cmd.Flags().GetDuration(suiteMaxWaitFlag)
	if err != nil {
		return err
	}
	if maxWait <= 0 {
		return fmt.Errorf("--%s must be more than zero, got %s", suiteMaxWaitFlag, maxWait)
	}
	// Checked before the suite starts, so a --timeout no wait can fit in does
	// not leave queued runs behind.
	requestTimeout, err := globalRequestTimeout(cmd)
	if err != nil {
		return err
	}
	if minTimeout := suiteWaitMinCallSeconds*time.Second + suiteWaitTimeoutHeadroom; requestTimeout > 0 && requestTimeout < minTimeout {
		return fmt.Errorf("--%s needs a --timeout of at least %s, since each wait holds the request for %ds or more; got %s",
			suiteWaitFlag, minTimeout, suiteWaitMinCallSeconds, requestTimeout)
	}
	req, err := flagutil.BuildRequest[operations.StableTestRunControllerCreateSuiteRequest](cmd, createSuiteCmdMeta, "Body", "body")
	if err != nil {
		return err
	}
	s, err := client.NewClient(cmd)
	if err != nil {
		return err
	}
	sdkOpts, err := output.PrepareCallOpts(cmd)
	if err != nil {
		return err
	}
	if err := output.ValidateGlobalServerIndex(cmd, len(sdk.ServerList)); err != nil {
		return err
	}

	created, err := s.Test.Run.CreateSuite(cmd.Context(), *req, sdkOpts...)
	if err != nil {
		return output.Error(cmd, err)
	}
	suite := created.GetStableTestRunSuiteResponse()
	if suite == nil {
		return errors.New("the API started the suite but returned no bulkID to wait for")
	}

	target := suiteTarget{projectID: req.ProjectID, environmentAlias: req.EnvironmentAlias, bulkID: suite.BulkID}
	runs := "runs"
	if len(suite.Runs) == 1 {
		runs = "run"
	}
	fmt.Fprintf(cmd.ErrOrStderr(), "Started suite %s with %d %s. Waiting up to %s for it to finish.\n",
		target.bulkID, len(suite.Runs), runs, maxWait)

	waited, err := waitForSuite(cmd, s, target, sdkOpts, maxWait, requestTimeout)
	if err != nil {
		return err
	}
	if err := output.Result(cmd, waited); err != nil {
		return err
	}
	return suiteOutcome(cmd, target, waited.GetStableTestRunSuiteWaitResponse(), maxWait)
}

type suiteTarget struct {
	projectID        string
	environmentAlias string
	bulkID           string
}

func (t suiteTarget) flags() string {
	return fmt.Sprintf("--project-id %s --environment-alias %s", t.projectID, t.environmentAlias)
}

// waitForSuite waits until the suite is done or maxWait has passed, and
// returns the last wait's response. Transient failures are retried, so one
// dropped request does not end a long wait, but a retry never waits past
// maxWait once there is a response to report.
func waitForSuite(
	cmd *cobra.Command,
	s *sdk.VoiceflowSDK,
	target suiteTarget,
	sdkOpts []operations.Option,
	maxWait time.Duration,
	requestTimeout time.Duration,
) (*operations.StableTestRunControllerWaitSuiteResponse, error) {
	ctx := cmd.Context()
	deadline := time.Now().Add(maxWait)
	var last *operations.StableTestRunControllerWaitSuiteResponse
	lastProgress := ""
	failures := 0

	for {
		seconds := suiteWaitSeconds(time.Until(deadline), requestTimeout)
		started := time.Now()
		res, err := waitOnce(ctx, s, operations.StableTestRunControllerWaitSuiteRequest{
			ProjectID:        target.projectID,
			EnvironmentAlias: target.environmentAlias,
			Body:             components.StableTestRunSuiteWaitRequest{BulkID: target.bulkID, TimeoutSeconds: &seconds},
		}, sdkOpts)
		if err != nil {
			if ctx.Err() == nil && isTransientWaitError(err) && failures < suiteWaitRetries && time.Until(deadline) > 0 {
				failures++
				delay := min(suiteWaitRetryDelay, time.Until(deadline))
				fmt.Fprintf(cmd.ErrOrStderr(), "Waiting for suite %s failed (%v). Retrying in %s.\n",
					target.bulkID, err, delay.Round(time.Second))
				if err := sleepContext(ctx, delay); err != nil {
					return nil, err
				}
				if time.Until(deadline) <= 0 && last != nil {
					return last, nil
				}
				continue
			}
			return nil, output.Error(cmd, err)
		}
		failures = 0

		result := res.GetStableTestRunSuiteWaitResponse()
		if result == nil {
			return nil, fmt.Errorf("the API returned no result while waiting for suite %s", target.bulkID)
		}
		last = res
		if result.Done || time.Until(deadline) <= 0 {
			return res, nil
		}
		if progress := suiteProgress(result.Counts); progress != lastProgress {
			lastProgress = progress
			fmt.Fprintf(cmd.ErrOrStderr(), "Suite %s: %s.\n", target.bulkID, progress)
		}
		if pause := min(suiteWaitMinInterval-time.Since(started), time.Until(deadline)); pause > 0 {
			if err := sleepContext(ctx, pause); err != nil {
				return nil, err
			}
		}
		if time.Until(deadline) <= 0 {
			return res, nil
		}
	}
}

// waitOnce makes one wait request, abandoned if the API has not answered well
// after the time it was asked to hold. The deadline is set on the context
// because WithOperationTimeout refuses every operation that does not support
// retries, WaitSuite included.
func waitOnce(
	ctx context.Context,
	s *sdk.VoiceflowSDK,
	req operations.StableTestRunControllerWaitSuiteRequest,
	sdkOpts []operations.Option,
) (*operations.StableTestRunControllerWaitSuiteResponse, error) {
	ctx, cancel := context.WithTimeout(ctx, time.Duration(*req.Body.TimeoutSeconds)*time.Second+suiteWaitRequestSlack)
	defer cancel()
	return s.Test.Run.WaitSuite(ctx, req, sdkOpts...)
}

// globalRequestTimeout is the --timeout every request is held to, resolved
// the way the client resolves it, or zero when there is none.
func globalRequestTimeout(cmd *cobra.Command) (time.Duration, error) {
	value, changed := flagutil.GetStringFlag(cmd, "timeout")
	if !changed || value == "" {
		value = config.GetString("timeout")
	}
	if value == "" {
		return 0, nil
	}
	timeout, err := time.ParseDuration(value)
	if err != nil {
		return 0, fmt.Errorf("invalid --timeout value %q: %w", value, err)
	}
	return timeout, nil
}

// suiteWaitSeconds is how long one wait asks the API to hold: 45 seconds, or
// less when --max-wait is nearly used up or --timeout would cut the request
// off first, but never under the 5 seconds the API needs at least.
func suiteWaitSeconds(remaining, requestTimeout time.Duration) int64 {
	seconds := min(int64(suiteWaitCallSeconds), int64(math.Ceil(remaining.Seconds())))
	if requestTimeout > 0 {
		seconds = min(seconds, int64((requestTimeout - suiteWaitTimeoutHeadroom).Seconds()))
	}
	return max(suiteWaitMinCallSeconds, seconds)
}

// isTransientWaitError reports whether a failed wait is worth repeating: a
// rate limit, a server error, or a request that never got an answer.
func isTransientWaitError(err error) bool {
	var apiErr *sdkerrors.SDKDefaultError
	if errors.As(err, &apiErr) {
		return apiErr.StatusCode == 429 || apiErr.StatusCode >= 500
	}
	var urlErr *url.Error
	return errors.As(err, &urlErr) || errors.Is(err, context.DeadlineExceeded)
}

func suiteProgress(counts components.StableTestRunSuiteCounts) string {
	parts := []string{fmt.Sprintf("%d of %d passed", counts.Passed, counts.Total)}
	if counts.Failed > 0 {
		parts = append(parts, fmt.Sprintf("%d failed", counts.Failed))
	}
	if counts.Canceled > 0 {
		parts = append(parts, fmt.Sprintf("%d canceled", counts.Canceled))
	}
	return strings.Join(append(parts, fmt.Sprintf("%d still going", counts.Unfinished)), ", ")
}

// suiteOutcome turns the final wait into the exit status: nil only when every
// run passed.
func suiteOutcome(
	cmd *cobra.Command,
	target suiteTarget,
	result *components.StableTestRunSuiteWaitResponse,
	maxWait time.Duration,
) error {
	counts := result.Counts
	if !result.Done {
		return suiteError(cmd, "test_suite_unfinished",
			fmt.Sprintf("%d of %d runs in suite %s were still going after %s", counts.Unfinished, counts.Total, target.bulkID, maxWait),
			[]string{
				fmt.Sprintf("Keep waiting: vf test run wait-suite %s --bulk-id %s", target.flags(), target.bulkID),
				fmt.Sprintf("Stop them: vf test run cancel %s --run-ids <id> (the runs still going are listed in the output)", target.flags()),
			})
	}
	if notPassed := counts.Failed + counts.Canceled; notPassed > 0 {
		return suiteError(cmd, "test_suite_failed",
			fmt.Sprintf("%d of %d runs in suite %s did not pass (%d failed, %d canceled)",
				notPassed, counts.Total, target.bulkID, counts.Failed, counts.Canceled),
			[]string{fmt.Sprintf("Read a run's logs: vf test run get %s --run-id <id>", target.flags())})
	}
	return nil
}

// suiteError reports a suite that did not pass. In agent mode that is the
// structured envelope every other failure uses; otherwise a message and hints
// on stderr.
func suiteError(cmd *cobra.Command, errorType, message string, hints []string) error {
	if output.IsAgentMode() {
		return output.AgentModeError(cmd, errorType, message, hints)
	}
	return errors.New(message + "\n  " + strings.Join(hints, "\n  "))
}

func sleepContext(ctx context.Context, duration time.Duration) error {
	timer := time.NewTimer(duration)
	defer timer.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-timer.C:
		return nil
	}
}
